void muisc_play_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_muisc_play_select_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_muisc_play_select_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_LEFT:
            {
                app_musicplayer_album_next(0);
                }
            break;

        case LV_KEY_RIGHT:
            {
                app_musicplayer_album_next(1);
                }
            break;

        case LV_KEY_UP:
            {
                uint32_t        vol = app_musicplayer_get_vol();

                if (vol < MUSIC_MVOL_LEVEL_MAX)
                    vol++;
                else 
                    vol = MUSIC_MVOL_LEVEL_MAX;

                app_musicplayer_set_vol(vol);


                lv_img_set_src(p_screen_param->obj_img_vol,ui_img_vol[vol]);

                }
            break;

        case LV_KEY_DOWN:
            {
                uint32_t        vol = app_musicplayer_get_vol();

                if (vol > MUSIC_MVOL_LEVEL_MIN)
                    vol--;
                else 
                    vol = MUSIC_MVOL_LEVEL_MIN;

                app_musicplayer_set_vol(vol);


                lv_img_set_src(p_screen_param->obj_img_vol,ui_img_vol[vol]);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                alv_am_win_enter(NULL,"music_option",NULL);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
            {
                app_musicplayer_play_pause();
                uint8_t         play_status = app_musicplayer_get_play_status();

                lv_img_set_src(p_screen_param->obj_img_play,ui_img_play_status[play_status]);
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}



